// backend/services/blockchain.js
// Connects the Node.js backend to the deployed Ethereum smart contracts

const { ethers } = require("ethers");
const addresses   = require("../../deployed-addresses.json");

// ABIs — generated by Hardhat after compilation (artifacts/contracts/*.json)
const LandNFTABI           = require("../../artifacts/contracts/LandNFT.sol/LandNFT.json").abi;
const LandRegistryABI      = require("../../artifacts/contracts/LandRegistry.sol/LandRegistry.json").abi;
const LandTransferABI      = require("../../artifacts/contracts/LandTransfer.sol/LandTransfer.json").abi;
const DisputeResolutionABI = require("../../artifacts/contracts/DisputeResolution.sol/DisputeResolution.json").abi;
const LandLoanABI          = require("../../artifacts/contracts/LandLoan.sol/LandLoan.json").abi;

// ─── Provider and signer ──────────────────────────────────────────────────────
const provider = new ethers.providers.JsonRpcProvider(
  process.env.RPC_URL || "http://127.0.0.1:8545"
);

// Backend wallet (used for admin/system calls like approvals)
const backendWallet = new ethers.Wallet(
  process.env.BACKEND_PRIVATE_KEY || "0xac0974bec39a17e36ba4a6b4d238ff944bacb478cbed5efcae784d7bf4f2ff80",
  provider
);

// ─── Contract instances ────────────────────────────────────────────────────────
const landNFT = new ethers.Contract(
  addresses.LandNFT, LandNFTABI, backendWallet
);
const landRegistry = new ethers.Contract(
  addresses.LandRegistry, LandRegistryABI, backendWallet
);
const landTransfer = new ethers.Contract(
  addresses.LandTransfer, LandTransferABI, backendWallet
);
const disputeResolution = new ethers.Contract(
  addresses.DisputeResolution, DisputeResolutionABI, backendWallet
);
const landLoan = new ethers.Contract(
  addresses.LandLoan, LandLoanABI, backendWallet
);

// ─── Service functions ────────────────────────────────────────────────────────

async function approveParcel(parcelId) {
  const tx     = await landRegistry.approveParcel(parcelId);
  const receipt = await tx.wait();

  // Find the ParcelApproved event to get tokenId
  const event  = receipt.events?.find(e => e.event === "ParcelApproved");
  const tokenId = event?.args?.tokenId?.toNumber() || null;

  return { txHash: receipt.transactionHash, blockNumber: receipt.blockNumber, tokenId };
}

async function getParcelFromChain(parcelId) {
  return await landRegistry.getParcel(parcelId);
}

async function verifyOwnership(parcelId) {
  const parcel  = await landRegistry.getParcel(parcelId);
  const tokenId = await landNFT.getTokenByParcel(parcelId).catch(() => null);
  const nftOwner = tokenId ? await landNFT.ownerOf(tokenId).catch(() => null) : null;

  return {
    parcelId,
    owner:        parcel.owner,
    status:       ["Pending","Approved","Rejected","Disputed"][parcel.status] || "Unknown",
    nftTokenId:   tokenId ? tokenId.toNumber() : null,
    nftOwner,
    registeredAt: parcel.registeredAt ? new Date(parcel.registeredAt.toNumber() * 1000) : null,
    isCollateral: parcel.isCollateral,
  };
}

async function createEscrow(parcelId, buyerAddress, priceWei) {
  const tx      = await landTransfer.createEscrow(parcelId, buyerAddress, priceWei);
  const receipt = await tx.wait();
  const event   = receipt.events?.find(e => e.event === "EscrowCreated");
  return { txHash: receipt.transactionHash, escrowId: event?.args?.escrowId?.toNumber() };
}

async function fileDispute(parcelId, description, evidenceIPFSHash, bondWei) {
  const tx      = await disputeResolution.fileDispute(parcelId, description, evidenceIPFSHash, { value: bondWei });
  const receipt = await tx.wait();
  const event   = receipt.events?.find(e => e.event === "DisputeFiled");
  return { txHash: receipt.transactionHash, disputeId: event?.args?.disputeId?.toNumber() };
}

async function assignArbitrators(disputeId) {
  const tx      = await disputeResolution.assignArbitrators(disputeId);
  const receipt = await tx.wait();
  return { txHash: receipt.transactionHash };
}

async function getTotalStats() {
  const [totalParcels, totalMinted, totalDisputes, totalLoans] = await Promise.all([
    landRegistry.totalParcels(),
    landNFT.totalMinted(),
    disputeResolution.totalDisputes(),
    landLoan.totalLoans(),
  ]);
  return {
    totalParcels:  totalParcels.toNumber(),
    totalNFTs:     totalMinted.toNumber(),
    totalDisputes: totalDisputes.toNumber(),
    totalLoans:    totalLoans.toNumber(),
  };
}

module.exports = {
  approveParcel,
  getParcelFromChain,
  verifyOwnership,
  createEscrow,
  fileDispute,
  assignArbitrators,
  getTotalStats,
  contracts: { landNFT, landRegistry, landTransfer, disputeResolution, landLoan },
  provider,
};
